CREATE TABLE ibexa_token (id INT AUTO_INCREMENT NOT NULL, type_id INT NOT NULL, token VARCHAR(255) NOT NULL, identifier VARCHAR(128) DEFAULT NULL, created INT DEFAULT 0 NOT NULL, expires INT DEFAULT 0 NOT NULL, revoked TINYINT(1) DEFAULT '0' NOT NULL, INDEX IDX_B5412887C54C8C93 (type_id), UNIQUE INDEX ibexa_token_unique (token, identifier, type_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
